css:
.page {
  display: flex;
  flex-direction: column;
  min-height: 360px;
  border: 2px dashed #a1a1aa;
}

.head,
.foot {
  flex-shrink: 0;
  padding: 12px 16px;
  background: #18181b;
  color: #fafafa;
}

.middle {
  display: flex;
  flex: 1;
  gap: 8px;
  padding: 8px;
}

.side,
.extra {
  flex: 0 0 120px;
  padding: 12px;
  background: #fed7aa;
  border: 1px solid #f97316;
  border-radius: 6px;
}

.content {
  flex: 1;
  min-width: 0;
  padding: 12px;
  background: #fafafa;
  border: 1px solid #d4d4d8;
  border-radius: 6px;
}
